INSERT INTO pos_demo.products(sku,label,unit_price,currency) VALUES('DEMO-POS-001','Synthetic notebook',4000,'UGX'),('DEMO-POS-002','Synthetic bottle',18000,'UGX'),('DEMO-POS-003','Synthetic tea pack',2500,'UGX') ON CONFLICT(sku) DO NOTHING;
INSERT INTO pos_demo.stock_events(product_id,quantity_delta,reason,source_ref) SELECT product_id,qty,'opening',src FROM (VALUES('DEMO-POS-001',100,'OPEN-POS-001'),('DEMO-POS-002',40,'OPEN-POS-002'),('DEMO-POS-003',250,'OPEN-POS-003')) v(sku,qty,src) JOIN pos_demo.products p ON p.sku=v.sku ON CONFLICT(source_ref) DO NOTHING;
INSERT INTO pos_demo.sales(receipt_ref,terminal_ref,occurred_at,currency,status,idempotency_key) VALUES('DEMO-RECEIPT-001','DEMO-TERM-A',TIMESTAMPTZ '2026-10-01 09:00+00','UGX','posted','DEMO-SALE-KEY-001'),('DEMO-RECEIPT-002','DEMO-TERM-A',TIMESTAMPTZ '2026-10-02 11:00+00','UGX','posted','DEMO-SALE-KEY-002') ON CONFLICT(receipt_ref) DO NOTHING;
INSERT INTO pos_demo.sale_lines(sale_id,product_id,quantity,unit_price) SELECT s.sale_id,p.product_id,v.qty,v.price FROM (VALUES('DEMO-RECEIPT-001','DEMO-POS-001',2,4000::numeric),('DEMO-RECEIPT-001','DEMO-POS-003',5,2500::numeric),('DEMO-RECEIPT-002','DEMO-POS-002',1,18000::numeric)) v(receipt,sku,qty,price) JOIN pos_demo.sales s ON s.receipt_ref=v.receipt JOIN pos_demo.products p ON p.sku=v.sku ON CONFLICT(sale_id,product_id) DO NOTHING;
INSERT INTO pos_demo.stock_events(product_id,quantity_delta,reason,source_ref) SELECT p.product_id,-v.qty,'sale',v.src FROM (VALUES('DEMO-POS-001',2,'SALE-POS-001'),('DEMO-POS-003',5,'SALE-POS-002'),('DEMO-POS-002',1,'SALE-POS-003')) v(sku,qty,src) JOIN pos_demo.products p ON p.sku=v.sku ON CONFLICT(source_ref) DO NOTHING;